  AND NOT EXISTS (
    SELECT 1 FROM price_versions cur
    WHERE cur.model_product_id = mp.id
      AND cur.effective_to IS NULL
      AND cur.input_per_million = 1.78571400
      AND cur.output_per_million = 3.57142900
      AND cur.cache_read_per_million = 0.00000000);

-- Qwen Plus  (qwen/qwen3.7-plus)  ->  $0.29761900/$1.19047600 per M
UPDATE price_versions pv
SET effective_to = now()
FROM model_products mp
WHERE mp.public_name = 'qwen-plus'
  AND pv.model_product_id = mp.id
  AND pv.effective_to IS NULL
  AND (pv.input_per_million <> 0.29761900 OR pv.output_per_million <> 1.19047600 OR pv.cache_read_per_million <> 0.05952400);
INSERT INTO price_versions (model_product_id, version, currency, input_per_million, output_per_million, cache_read_per_million, effective_from)
SELECT mp.id,
       (SELECT COALESCE(MAX(version), 0) + 1 FROM price_versions WHERE model_product_id = mp.id),
       'USD', 0.29761900, 1.19047600, 0.05952400, now()
FROM model_products mp
WHERE mp.public_name = 'qwen-plus'
  AND NOT EXISTS (
    SELECT 1 FROM price_versions cur
    WHERE cur.model_product_id = mp.id
      AND cur.effective_to IS NULL
      AND cur.input_per_million = 0.29761900
      AND cur.output_per_million = 1.19047600
      AND cur.cache_read_per_million = 0.05952400);

COMMIT;
